function sanitizeSettings(settings){const out={};for(const [k,v]of Object.entries(settings||{})){if(/api.?key|token|credential|password|open.?meteo.*key|weather.*key/i.test(k))continue;let clean=v;try{clean=JSON.stringify(scrub(JSON.parse(v)));}catch(e){if(e.message==='Unsafe object key in backup.'||e.message==='Backup nesting is too deep.')throw e;}const name=/^flightdesk-weather-(?:links|services|subscription)/.test(k)?'flightdesk-retired-weather-links-v1':k;out[name]=clean;}return out;}
const obj=x=>x&&typeof x==='object'&&!Array.isArray(x),str=x=>typeof x==='string',arr=(x,label)=>{if(!Array.isArray(x)||x.length>10000)throw Error('Invalid '+label);return x;};
function validate(value){scrub(value);if(!obj(value)||value.format!=='flightdesk-backup'||value.version!==1||!obj(value.profiles)||value.profiles.version!==1||!obj(value.flights)||value.flights.version!==1)throw Error('Use a complete Flightdesk backup file (version 1).');const p=value.profiles;
for(const name of ['pilots','operators'])for(const r of arr(p[name],name)){if(!obj(r)||!str(r.key)||!str(r.name)||!str(r.registration)||!str(r.expiry))throw Error('Invalid crew profile');}
for(const name of ['batteries','removedBatteries']){const list=name==='removedBatteries'?(p[name]||[]):p[name];for(const r of arr(list,name)){if(!obj(r)||!str(r.key)||!str(r.name)||!str(r.type)||!(r.soc===null||Number.isFinite(r.soc))||!Number.isInteger(r.units)||!str(r.health)||!str(r.inspection))throw Error('Invalid battery record');}}
for(const r of arr(p.batteryChanges||[],'battery changes')){if(!obj(r)||!str(r.key)||!Array.isArray(r.spreads)||!r.spreads.every(v=>v===null||Number.isFinite(v))||!str(r.failedKey)||!str(r.failedName)||!str(r.failedAt))throw Error('Invalid battery history');if(r.readings!==undefined&&(!Array.isArray(r.readings)||!r.readings.every(obj)))throw Error('Invalid battery readings');}
for(const r of arr(value.flights.records,'flight records')){if(!obj(r)||r.schemaVersion!==1||!str(r.id)||!str(r.projectTitle)||!str(r.missionTitle)||!str(r.savedAt)||!obj(r.values)||!obj(r.readiness)||typeof r.readiness.go!=='boolean'||!str(r.readiness.scope)||!Array.isArray(r.checks)||!r.checks.every(obj)||!Array.isArray(r.cellReadings)||!r.cellReadings.every(obj)||!Array.isArray(r.batteryChanges))throw Error('Invalid flight snapshot');if(r.site!==null&&r.site!==undefined&&(!obj(r.site)||!Number.isFinite(r.site.lat)||!Number.isFinite(r.site.lon)))throw Error('Invalid saved site');}
if(value.settings!==undefined){if(!obj(value.settings))throw Error('Invalid saved app settings');for(const[k,v]of Object.entries(value.settings))if(!k.startsWith('flightdesk-')||['flightdesk-local-profiles-v1','flightdesk-flight-records-v1'].includes(k)||!str(v))throw Error('Invalid saved app setting');}
if(value.settings)value.settings=sanitizeSettings(value.settings);return value;}

function canonical(value){if(Array.isArray(value))return '['+value.map(canonical).join(',')+']';if(value&&typeof value==='object')return '{'+Object.keys(value).sort().map(k=>JSON.stringify(k)+':'+canonical(value[k])).join(',')+'}';return JSON.stringify(value);}
function strictMerge(existing,incoming,id,label){const out=[...existing],byId=new Map(existing.map(r=>[r[id],r]));for(const r of incoming){if(!r||typeof r[id]!=='string')throw Error('Invalid '+label+' identifier');if(byId.has(r[id])){if(canonical(byId.get(r[id]))!==canonical(r))throw Error('Conflicting '+label+' ID '+r[id]+': existing and imported revisions differ. Export both copies and resolve this conflict before merging.');}else{byId.set(r[id],r);out.push(r);}}return out;}
function validateSorties(value,validator){if(validator)return validator(value);if(!value||value.version!==1||!Array.isArray(value.sorties)||value.sorties.some(r=>!r||typeof r.id!=='string'||!Array.isArray(r.events)||!Array.isArray(r.debriefs)))throw Error('Invalid imported flight log');if(value.sorties.filter(r=>r.phase==='AIRBORNE').length>1)throw Error('More than one active flight in imported logs');return value;}
function mergeSettings(existing,incoming,lifecycleValidator){const clean=sanitizeSettings(incoming),out={...existing};for(const [name,text]of Object.entries(clean)){const current=existing[name];if(name==='flightdesk-sorties-v1'){const add=validateSorties(parse(text),lifecycleValidator),old=current?validateSorties(parse(current),lifecycleValidator):{version:1,sorties:[]};out[name]=JSON.stringify(validateSorties({version:1,sorties:strictMerge(old.sorties,add.sorties,'id','sortie')},lifecycleValidator));}else if(name==='flightdesk-debrief-drafts-v1'){const add=validateDebriefDrafts(parse(text)),old=current?validateDebriefDrafts(parse(current)):{version:1,drafts:{}};const drafts={...old.drafts};for(const [id,d]of Object.entries(add.drafts)){if(drafts[id]&&canonical(drafts[id])!==canonical(d))throw Error('Conflicting debrief recovery draft for '+id+'. Keep both backups; save/discard the unfinished draft explicitly before importing.');drafts[id]=d;}out[name]=JSON.stringify({version:1,drafts});}else if(name==='flightdesk-maintenance-v1'){const add=parse(text),old=current?parse(current):{version:1,events:[]};for(const v of [old,add])if(!v||v.version!==1||!Array.isArray(v.events)||v.events.some(e=>!e||typeof e.id!=='string'))throw Error('Invalid maintenance event archive');out[name]=JSON.stringify({version:1,events:strictMerge(old.events,add.events,'id','maintenance event')});}else if(name==='flightdesk-operating-profiles-v1'){const add=parse(text),old=current?parse(current):[];if(!Array.isArray(add)||!Array.isArray(old))throw Error('Invalid operating profiles');out[name]=JSON.stringify(strictMerge(old,add,'id','operating profile'));}else if(current===undefined||current===null)out[name]=text;}return out;}


function validateDebriefDrafts(value){if(!value||value.version!==1||!obj(value.drafts)||Object.keys(value.drafts).length>10000)throw Error('Invalid debrief recovery drafts');for(const[id,d]of Object.entries(value.drafts))if(!id||!obj(d)||!Number.isFinite(Date.parse(d.savedAt))||!obj(d.data)||Object.values(d.data).some(v=>!['string','boolean'].includes(typeof v)))throw Error('Invalid debrief recovery draft');return value;}

function readProfiles(raw){if(raw===null)return null;const profiles=parse(raw);return validate({format:'flightdesk-backup',version:1,profiles,flights:{version:1,records:[]}}).profiles;}
function readFlights(raw){if(raw===null)return null;const flights=parse(raw);return validate({format:'flightdesk-backup',version:1,profiles:{version:1,pilots:[],operators:[],batteries:[],removedBatteries:[],batteryChanges:[]},flights}).flights;}

function merge(existing,incoming,id){const keys=new Set(existing.map(r=>r[id])),result=[...existing];for(const r of incoming)if(!keys.has(r[id])){keys.add(r[id]);result.push(r);}return result;}
function reportHTML(records,exportedAt,flightLog=null){
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const status=r=>r.readiness?.status==='warning'?'WARNING':r.readiness?.go?'GO':'NO-GO';
return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Flightdesk UK · saved flight records</title><style>body{font:14px/1.5 system-ui,sans-serif;color:#152f3b;max-width:1100px;margin:32px auto;padding:0 20px}h1{font-size:26px}h2{font-size:20px}table{border-collapse:collapse;width:100%;margin:18px 0}th,td{padding:9px;border:1px solid #ccd6dc;text-align:left;vertical-align:top}th{background:#f1f5f7}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:11px/1.5 monospace;background:#f5f7f8;padding:14px}article{border-top:2px solid #ccd6dc;margin-top:30px;padding-top:12px}@media print{body{margin:0;padding:0}article{break-before:page}tr{break-inside:avoid}pre{font-size:9px}}</style></head><body><h1>Flightdesk UK · saved flight records</h1><p>Exported at '+escape(exportedAt)+' · '+records.length+' saved snapshot(s). All timestamps are shown as recorded; schedule fields use Europe/London.</p><p>Pilot-recorded planning records. Readiness is historical, not independent verification of compliance, flight clearance or proof a flight took place. Multiple snapshots may belong to the same mission. Drafts and active-flight logs are included in the separate all-data JSON backup; this snapshot report does not replace that backup. These local records are not cryptographically tamper-proof or a certified logbook. This report contains personal and site information: review before sharing.</p><p>Use the browser Print / Save as PDF menu for a PDF copy. Keep the separate JSON backup for restoration; this report cannot be imported.</p>'+(records.length?'<table><thead><tr><th>Project / mission</th><th>Saved at</th><th>Take-off · London time</th><th>Aircraft</th><th>Readiness at save</th></tr></thead><tbody>'+records.map(r=>'<tr><td>'+escape(r.projectTitle)+' / '+escape(r.missionTitle)+'</td><td>'+escape(r.savedAt)+'</td><td>'+escape(r.values?.date)+' '+escape(r.values?.hour)+':'+escape(r.values?.startminute||'00')+'</td><td>'+escape(r.values?.aircraft||r.values?.aircraftselect)+'</td><td>'+status(r)+'</td></tr>').join('')+'</tbody></table>':'<p>No saved flight records were present when this report was downloaded.</p>')+records.map((r,i)=>'<article><h2>'+String(i+1)+'. '+escape(r.projectTitle)+' / '+escape(r.missionTitle)+'</h2><p>Snapshot ID: '+escape(r.id)+' · Mission ID: '+escape(r.missionId)+' · Saved: '+escape(r.savedAt)+' · '+status(r)+'</p><h3>Complete saved snapshot</h3><p>Includes the checks, notes, declarations, recorded forecast/airspace evidence and battery information present when saved. Missing information has not been reconstructed.</p><pre>'+escape(JSON.stringify(r,null,2))+'</pre></article>').join('')+(flightLog?'<article><h2>Actual flight events and post-flight revisions</h2><p>Pilot-entered times and outcomes, including missing values and revisions; no telemetry or independent verification. Cancelled plans do not represent flights. App versions and original briefings are preserved below.</p><pre>'+escape(JSON.stringify(flightLog,null,2))+'</pre></article>':'')+'</body></html>';
}
function clearAppStorage(storage){const keys=[];for(let i=0;i<storage.length;i++){const k=storage.key(i);if(k?.startsWith('flightdesk-'))keys.push(k);}for(const k of keys)storage.removeItem(k);for(const k of keys)if(storage.getItem(k)!==null)throw Error('Some app data could not be removed.');return keys.length;}
